        half = (len(s) + 1) // 2
        left_part = s[:half]
        incremented = str(int(left_part) + 1)
        # If incrementing left half increases length, e.g. 999 -> 1000
        if len(incremented) > len(left_part):
            # This means palindrome length increases by 1
