def min_Jumps(d: float, length: float, *extra_args) -> int:
    if d == 0:
        return 0
    if length == 0:
        return float('inf')  # cannot move if jump length is zero
    if length == d:
        return 1
    if length > d:
        # If one jump is longer than d, check if we can reach (d,0) in one jump:
        # The jump can be in any direction, so if length > d, 
        # but length != d, can we reach (d,0) exactly?
        # Since jump length is fixed and not equal to d, one jump can't land exactly at (d,0).
        # So in that case, two jumps are needed.
        return 2
    # If length < d, minimum number of jumps is ceil(d/length)
    return math.ceil(d / length)

